# ---- rmw_fastrtps_shared_cpp: GUID / sequence-number helpers
R = f'{W}/rmw_fastrtps_shared_cpp'
patch(f'{R}/include/rmw_fastrtps_shared_cpp/guid_utils.hpp', [(
'''#include "fastdds/rtps/common/Guid.h"
''',
'''#include <cstdint>

#include "fastdds/rtps/common/Guid.h"
#include "fastdds/rtps/common/SequenceNumber.h"
'''), (
'''struct hash_fastrtps_guid
{''',
'''// FISH (fastdds1): the sample identity as integers — writer GUID (12-byte prefix + 4-byte entity id) as two u64,
// big-endian byte order, and the 64-bit sequence number.
inline uint64_t
fish_guid_hi(const eprosima::fastrtps::rtps::GUID_t & g)
{
  uint64_t v = 0;
  for (int i = 0; i < 8; ++i) {v = (v << 8) | static_cast<uint64_t>(g.guidPrefix.value[i]);}
  return v;
}

inline uint64_t
fish_guid_lo(const eprosima::fastrtps::rtps::GUID_t & g)
{
  uint64_t v = 0;
  for (int i = 8; i < 12; ++i) {v = (v << 8) | static_cast<uint64_t>(g.guidPrefix.value[i]);}
  for (int i = 0; i < 4; ++i) {v = (v << 8) | static_cast<uint64_t>(g.entityId.value[i]);}
  return v;
}

inline uint64_t
fish_seq(const eprosima::fastrtps::rtps::SequenceNumber_t & s)
{
  return (static_cast<uint64_t>(static_cast<uint32_t>(s.high)) << 32) | static_cast<uint64_t>(s.low);
}

struct hash_fastrtps_guid
{''')])

